\title{Stochastic Galois Theory over Finite Fields:\\
Exact Factorization Statistics and a Cyclic Obstruction}
\author{Aristotle}
\date{July 10, 2026}

\begin{document}

\begin{abstract}
Over the rational numbers, a classical principle (the probabilistic form of
Hilbert's irreducibility theorem) states that a ``random'' polynomial of degree
$n$ has Galois group equal to the full symmetric group $S_n$. One might conjecture
an analogue over finite fields: that for a uniformly random monic polynomial
$f \in \FF_q[x]$ of fixed degree $n$, the Galois group is $S_n$ with probability
tending to $1$ as $q \to \infty$. We show this is \emph{false at the
group-theoretic level}. The absolute Galois group of a finite field is procyclic,
so every Galois group arising over a finite field is cyclic, hence abelian; since
$S_n$ is non-abelian for $n \ge 3$, no polynomial over a finite field has Galois
group $S_n$ when $n \ge 3$. The probability is exactly $0$. What survives is the
statistics of the \emph{Frobenius cycle type}, i.e.\ the factorization type. We
establish two exact instances: an \emph{expected-roots identity} (summed over all
$q^n$ monic degree-$n$ polynomials, the total number of roots in $\FF_q$ --- indeed
over any finite commutative ring of cardinality $q$ --- is exactly $q^n$, so the
expected number of roots is exactly $1$, mirroring the mean number of fixed points
of a uniform permutation in $S_n$), and a complete \emph{degree-two census} (over
$\FF_q$ with $q$ odd: exactly $q$ monic quadratics have a repeated root, exactly
$q(q+1)/2$ are reducible, and exactly $q(q-1)/2$ are irreducible, so the proportion
irreducible tends to $1/2$, matching the fraction of transpositions in $S_2$). All
proofs are by elementary double-counting and completing the square.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The classical picture over $\QQ$}
Let $f \in \QQ[x]$ be separable of degree $n$ with splitting field $L$. The Galois
group $\Gal(L/\QQ)$ acts faithfully on the $n$ roots of $f$, embedding as a subgroup
of $S_n$. A guiding theme of arithmetic statistics is that this subgroup is
generically all of $S_n$: the proportion of degree-$n$ integer polynomials with
coefficients bounded by $H$ whose Galois group is a proper subgroup of $S_n$ tends to
$0$ as $H \to \infty$. Informally, \emph{a random polynomial over $\QQ$ has maximal
Galois group}.

\subsection{The tempting --- but false --- finite-field analogue}
Fix $n$ and let $f$ range uniformly over monic degree-$n$ polynomials in $\FF_q[x]$.
Does $\Gal(f) \cong S_n$ with probability approaching $1$ as $q \to \infty$? We show
the conjecture is false, and not merely quantitatively: the probability is
identically $0$ for all $n \ge 3$ and all $q$. The obstruction is structural
(Section~\ref{sec:cyclic}).

\subsection{The correct analogue: Frobenius cycle statistics}
The salvageable content of the ``random polynomial $\approx$ random permutation''
heuristic is not the isomorphism type of the Galois group but the \emph{cycle type
of the Frobenius automorphism} on the roots. For squarefree $f \in \FF_q[x]$, the
$q$-power Frobenius permutes the roots with cycle lengths equal to the degrees of
the irreducible factors of $f$. The correct theorem is that as $q \to \infty$ the
factorization type of a random monic degree-$n$ polynomial converges in
distribution to the cycle type of a uniform element of $S_n$. Sections~\ref{sec:roots}
and~\ref{sec:deg2} give two exact, unconditional instances.

\section{Definitions and setup}
Throughout, $K$ is a finite commutative ring with $q := |K|$; in
Sections~\ref{sec:cyclic} and~\ref{sec:deg2} we specialize to a finite field, and
in Section~\ref{sec:deg2} to odd characteristic.

\begin{definition}[Monic encoding]
A monic polynomial of degree $n \ge 1$ over $K$,
$f(x) = x^n + \sum_{i=0}^{n-1} v_i x^i$, is encoded by its coefficient vector
$v = (v_0,\dots,v_{n-1}) \in K^n$; there are exactly $q^n$ of them. We write
$\ev_n(v,r) := r^n + \sum_{i=0}^{n-1} v_i r^i$.
\end{definition}

\begin{definition}[Root count]
For monic $f$ encoded by $v$, its root set in $K$ is
$\{ r \in K : \ev_n(v,r) = 0 \}$. In degree $2$, with $f = x^2 + bx + c$ encoded by
$(b,c)$, set $\nroots(b,c) := \#\{ r \in K : r^2 + br + c = 0 \}$.
\end{definition}

\begin{definition}[Frobenius cycle type / factorization type]
For squarefree $f \in \FF_q[x]$ of degree $n$ with distinct irreducible factors of
degrees $d_1,\dots,d_k$ ($\sum d_j = n$), the factorization type is the partition
$(d_1,\dots,d_k)$. The $q$-power Frobenius acts on the $n$ roots as a permutation
of cycle type $(d_1,\dots,d_k)$; linear factors $x-r$ (roots in $\FF_q$) correspond
to fixed points, irreducible quadratics to $2$-cycles, etc.
\end{definition}

\section{The cyclic obstruction: correcting the conjecture}\label{sec:cyclic}

\begin{theorem}[Finite-field Galois groups are never $S_n$ for $n \ge 3$]
\label{thm:cyclic}
Let $L/K$ be an extension of fields with $L$ finite, and let $n \ge 3$. Then there
is no group isomorphism between $\Aut(L/K)$ (the Galois group when $L/K$ is Galois)
and $S_n$.
\end{theorem}

\begin{proof}
\emph{(i) Finite-field Galois groups are cyclic.} If $L$ is finite, then $L/K$ is a
Galois extension of finite fields and $\Gal(L/K)$ is generated by the relative
Frobenius $x \mapsto x^{|K|}$; hence it is cyclic, therefore abelian.
\emph{(ii) $S_n$ is non-abelian for $n \ge 3$.} The transpositions $(1\,2)$ and
$(2\,3)$ do not commute: $(2\,3)(1\,2)$ sends $1 \mapsto 3$, while $(1\,2)(2\,3)$
sends $1 \mapsto 2$. Now if $\varphi:\Gal(L/K)\to S_n$ were an isomorphism, then
$S_n$ would be cyclic, hence abelian, contradicting (ii). No such isomorphism
exists.
\end{proof}

\begin{corollary}[The conjecture fails identically]
For every fixed $n \ge 3$ and every prime power $q$,
$\PR_{f}(\Gal(f) \cong S_n) = 0$, where $f$ is uniform over monic degree-$n$
polynomials. This is exact, not asymptotic.
\end{corollary}

\begin{remark}
Over $\QQ$ the absolute Galois group is highly non-abelian and generic polynomials
realize $S_n$. Over $\FF_q$ the absolute Galois group $\widehat{\ZZ}$ is procyclic,
so every Galois group is a finite cyclic quotient. The finite-field theory is
governed not by which group appears (always cyclic) but by the permutation
representation of Frobenius on the roots --- its cycle type.
\end{remark}

\section{The expected-roots identity in every degree}\label{sec:roots}

\begin{lemma}[Fiber count]\label{lem:fiber}
Let $K$ be a finite commutative ring with $q = |K|$, fix $r \in K$ and degree
$m+1 \ge 1$. Then $\#\{ v \in K^{m+1} : \ev_{m+1}(v,r) = 0 \} = q^m$.
\end{lemma}

\begin{proof}
The condition reads $v_0 = -\big(r^{m+1} + \sum_{i=1}^m v_i r^i\big)$. For any
$(v_1,\dots,v_m) \in K^m$ the constant coefficient $v_0$ is uniquely determined, so
the solution set is the graph of a map $K^m \to K$, of cardinality $q^m$.
\end{proof}

\begin{theorem}[Expected-roots identity]\label{thm:roots}
Let $K$ be a finite commutative ring with $q = |K|$, and $n \ge 1$. Then
\[
  \sum_{v \in K^n} \#\{ r \in K : \ev_n(v,r) = 0 \} = q^n,
\]
so the expected number of roots of a uniformly random monic degree-$n$ polynomial
is exactly $\tfrac{1}{q^n}\sum_v \#\{ r : \ev_n(v,r)=0 \} = 1$.
\end{theorem}

\begin{proof}
Write $n = m+1$. The left side counts incidences $(v,r)$ with $\ev_n(v,r)=0$.
Exchanging the order of summation,
\[
  \sum_{v} \#\{ r : \ev_n(v,r)=0 \}
  = \sum_{r \in K} \#\{ v : \ev_n(v,r)=0 \}
  = \sum_{r \in K} q^m = q \cdot q^m = q^n,
\]
using Lemma~\ref{lem:fiber}. Dividing by $q^n$ gives mean $1$.
\end{proof}

\begin{corollary}[Prime-field form]
For a prime $p$ and $n \ge 1$,
$\sum_{v \in \FF_p^{\,n}} \#\{ r \in \FF_p : \ev_n(v,r)=0 \} = p^n.$
\end{corollary}

Linear factors $x-r$ are the fixed points of Frobenius; Theorem~\ref{thm:roots}
says their average count is exactly $1$, matching the mean number of fixed points
of a uniform permutation in $S_n$.

\section{The complete degree-two census}\label{sec:deg2}
Fix a finite field $K$ of odd characteristic, $q = |K|$; there are $q^2$ monic
quadratics $x^2 + bx + c$ encoded by $(b,c) \in K^2$.

\begin{lemma}[Roots via the discriminant]\label{lem:disc}
If $\charr(K) \ne 2$, then $\nroots(b,c) = \#\{ y \in K : y^2 = b^2 - 4c \}$.
\end{lemma}

\begin{proof}
Completing the square, $r^2 + br + c = 0 \iff (2r+b)^2 = b^2 - 4c$. Since $2 \ne 0$,
the map $r \mapsto 2r+b$ is a bijection of $K$ carrying the root set bijectively onto
the square roots of $b^2 - 4c$.
\end{proof}

\begin{lemma}[Square-root counts]\label{lem:sqrt}
In a field $K$ with $\charr(K) \ne 2$ and any $a \in K$:
(a) $\#\{ y : y^2 = a \} \le 2$; (b) $\#\{ y : y^2 = a \} = 1 \iff a = 0$.
\end{lemma}

\begin{proof}
(a) If $y_0^2 = a$ then $y^2 = a \iff y \in \{y_0,-y_0\}$; if none exists the count
is $0$. (b) A unique root $y$ forces $-y = y$, i.e.\ $2y = 0$, so $y = 0$ and
$a = 0$; conversely $a = 0$ gives the single root $y = 0$.
\end{proof}

\begin{corollary}
A monic quadratic over $K$ ($\charr \ne 2$) has $\nroots(b,c) \le 2$.
\end{corollary}

\begin{lemma}[Total incidences]\label{lem:sumnroots}
$\sum_{(b,c) \in K^2} \nroots(b,c) = q^2.$
\end{lemma}

\begin{proof}
Exchanging summation order,
$\sum_{(b,c)} \nroots(b,c) = \sum_{r} \#\{ (b,c) : r^2 + br + c = 0 \}$.
For fixed $r$, $c = -(r^2 + br)$ is forced for each of the $q$ values of $b$, so the
inner count is $q$; summing over the $q$ values of $r$ gives $q^2$.
\end{proof}

\begin{theorem}[Degree-two census]\label{thm:deg2}
Let $K$ be a finite field with $q = |K|$ odd. Among the $q^2$ monic quadratics:
\begin{enumerate}
\item exactly $q$ have a repeated root ($\nroots = 1$; the squares $(x-r)^2$);
\item $2 \cdot \#\{ (b,c) : \exists r,\ r^2+br+c=0 \} = q(q+1)$, i.e.\ exactly
      $\tfrac{q(q+1)}{2}$ are reducible;
\item $2 \cdot \#\{ (b,c) : \nexists r,\ r^2+br+c=0 \} = q(q-1)$, i.e.\ exactly
      $\tfrac{q(q-1)}{2}$ are irreducible.
\end{enumerate}
\end{theorem}

\begin{proof}
Let $n_0,n_1,n_2$ count quadratics with $0,1,2$ roots. By the corollary each
quadratic lies in exactly one class, so $n_0 + n_1 + n_2 = q^2$. Counting with
multiplicity, $\sum \nroots = n_1 + 2n_2 = q^2$ by Lemma~\ref{lem:sumnroots}. By
Lemmas~\ref{lem:disc} and~\ref{lem:sqrt}(b), $\nroots = 1 \iff b^2 - 4c = 0 \iff
c = b^2/4$; since $4 \ne 0$ this gives one $c$ per $b$, so $n_1 = q$. Then
$2n_2 = q^2 - q$, i.e.\ $n_2 = \tfrac{q(q-1)}{2}$, and $n_0 = q^2 - n_1 - n_2 =
\tfrac{q(q-1)}{2}$. Reducibles number $n_1 + n_2 = \tfrac{q(q+1)}{2}$; irreducibles
number $n_0 = \tfrac{q(q-1)}{2}$. Doubling gives the stated identities.
\end{proof}

\begin{corollary}[Prime-field form]
For an odd prime $p$,
$2 \cdot \#\{ (b,c) \in \FF_p^2 : x^2 + bx + c \text{ has no root in } \FF_p \} = p(p-1).$
\end{corollary}

\begin{corollary}[Limiting proportions]
As $q \to \infty$,
\[
  \frac{\#\{\text{repeated}\}}{q^2} = \frac1q \to 0, \quad
  \frac{\#\{\text{irreducible}\}}{q^2} = \frac{q-1}{2q} \to \frac12, \quad
  \frac{\#\{\text{reducible}\}}{q^2} = \frac{q+1}{2q} \to \frac12.
\]
\end{corollary}

Under the Frobenius dictionary the identity of $S_2$ corresponds to a split
quadratic and the transposition to an irreducible one; the factorization type of a
random quadratic thus converges to the cycle type of a uniform element of $S_2$.

\section{The corrected picture}
Group-theoretically, every Galois group over $\FF_q$ is cyclic and never $S_n$ for
$n \ge 3$, so $\PR(\Gal = S_n) = 0$. Statistically, the honest analogue is Frobenius
equidistribution: the factorization type of a random monic degree-$n$ polynomial
converges to the cycle type of a uniform element of $S_n$. Theorem~\ref{thm:roots}
(mean number of linear factors $= 1$ in all degrees) and Theorem~\ref{thm:deg2}
(the full degree-$2$ law) are the two cleanest exact instances.

\section{Algorithms and applications}
Root counting by evaluation costs $O(qn)$ operations; quadratic classification via
the discriminant and the Euler criterion $\Delta^{(q-1)/2}$ costs $O(\log q)$
multiplications; general factorization type is obtained by distinct-degree
factorization $\gcd(f, x^{q^d}-x)$. Applications include expected-time analysis of
factorization and irreducibility testing, and the density $\approx 1/n$ of degree-$n$
irreducibles (matching the fraction of $n$-cycles in $S_n$) governing
generate-and-test constructions in coding theory and cryptography.

\section{Future work}
(1) A full degree-three census (irreducibles $\to$ density $1/3$, matching
$3$-cycles). (2) The exact count $\tfrac1n\sum_{d\mid n}\mu(d)q^{n/d}$ of monic
irreducibles and, more finely, the exact number of each factorization type, with
$O(1/q)$ error. (3) Quantitative equidistribution: bounding the total-variation
distance to the uniform $S_n$ cycle-type law by $O_n(1/q)$. (4) Extensions to
non-monic families and to prime-power $q$ uniformly in $q$ and $n$.

\section{Conclusion}
Over finite fields the slogan ``random polynomials have Galois group $S_n$'' is
false: such Galois groups are cyclic and never $S_n$ for $n \ge 3$. The correct
analogue is equidistribution of Frobenius cycle types toward random-permutation
cycle types. We proved two exact instances: the expected number of roots is exactly
$1$ in every degree, and the degree-two census gives $q$ repeated-root,
$q(q+1)/2$ reducible, and $q(q-1)/2$ irreducible monic quadratics. Randomness over
finite fields is not maximally complex in the group sense but maximally generic in
the statistical sense.

