from itertools import product
from typing import Tuple

def eval_monic(coeffs: Tuple[int, ...], r: int, p: int) -> int:
    """Evaluate x^n + sum_i coeffs[i] x^i at r modulo p."""
    val = pow(r, len(coeffs), p)
    for i, c in enumerate(coeffs):
        val = (val + c * pow(r, i, p)) % p
    return val

def count_roots(coeffs: Tuple[int, ...], p: int) -> int:
    return sum(1 for r in range(p) if eval_monic(coeffs, r, p) == 0)

def expected_roots_identity(p: int, n: int) -> None:
    """Verify: sum over all p^n monic degree-n polys of #roots = p^n, mean = 1."""
    total = sum(count_roots(c, p) for c in product(range(p), repeat=n))
    print(f"p={p} n={n}: total roots={total}, p^n={p**n}, mean={total/p**n:.4f}")

for p in (3, 5, 7):
    for n in (1, 2, 3):
        expected_roots_identity(p, n)

from typing import Dict

def count_roots_quadratic(b: int, c: int, p: int) -> int:
    return sum(1 for r in range(p) if (r*r + b*r + c) % p == 0)

def degree_two_census(p: int) -> Dict[str, int]:
    """Exact census of the p^2 monic quadratics x^2+bx+c over F_p (p odd)."""
    rep = red = irr = 0
    for b in range(p):
        for c in range(p):
            nr = count_roots_quadratic(b, c, p)
            rep += (nr == 1); red += (nr >= 1); irr += (nr == 0)
    assert rep == p
    assert red == p * (p + 1) // 2
    assert irr == p * (p - 1) // 2
    return {"repeated": rep, "reducible": red, "irreducible": irr,
            "irr_fraction": irr / p**2}

for p in (3, 5, 7, 11, 13, 101):
    print(p, degree_two_census(p))

from itertools import product
from math import factorial
from typing import Dict, List, Tuple

def roots_with_mult(coeffs: List[int], p: int) -> List[int]:
    """List roots in F_p of a monic poly (ascending coeffs) with multiplicity."""
    roots, poly, changed = [], coeffs[:], True
    while changed and len(poly) > 1:
        changed = False
        for r in range(p):
            v = 0
            for c in reversed(poly):
                v = (v * r + c) % p
            if v == 0:
                deg = len(poly) - 1
                quo, rem = [0]*deg, poly[-1]
                for i in range(deg-1, -1, -1):
                    quo[i] = rem; rem = (poly[i] + r*rem) % p
                poly, changed = quo, True
                roots.append(r); break
    return roots

def factorization_type(coeffs: Tuple[int, ...], p: int) -> Tuple[int, ...]:
    """Frobenius cycle type (partition of n) for small degree n <= 3."""
    n = len(coeffs)
    lin = roots_with_mult(list(coeffs) + [1], p)
    degs = [1]*len(lin)
    if n - len(lin) >= 2:
        degs.append(n - len(lin))
    return tuple(sorted(degs))

def sn_partition_probs(n: int) -> Dict[Tuple[int, ...], float]:
    def parts(m, mx):
        if m == 0: return [()]
        out = []
        for k in range(min(m, mx), 0, -1):
            for rest in parts(m-k, k): out.append((k,)+rest)
        return out
    d = {}
    for pt in parts(n, n):
        cnt = {}
        for x in pt: cnt[x] = cnt.get(x, 0)+1
        den = 1
        for k, m in cnt.items(): den *= (k**m)*factorial(m)
        d[tuple(sorted(pt))] = 1/den
    return d

n = 3
sn = sn_partition_probs(n)
for p in (5, 7, 11, 23):
    emp = {}
    for c in product(range(p), repeat=n):
        ft = factorization_type(c, p)
        if sum(ft) == n: emp[ft] = emp.get(ft, 0)+1
    tot = sum(emp.values())
    print(f"F_{p}:", {k: round(emp.get(k,0)/tot, 3) for k in sorted(sn, reverse=True)})
print("S_3 :", {k: round(v, 3) for k, v in sorted(sn.items(), reverse=True)})

